#define _POSIX_C_SOURCE 200809L
/*
 * Linear solver (n = 2..4) against exact-Fraction references generated by tests/tools/make_simul_cases.py.
 * These systems have large or long coefficients that cannot be typed into the editor (token limit), so the
 * solver is called directly. Unique solutions must match to 1e-9 relative; inconsistent and underdetermined
 * systems must be classified exactly.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "solvers/eqn.h"

int main(int argc, char **argv)
{
    FILE *f;
    char line[4096];
    int ln = 0, cases = 0, fails = 0;
    if (argc < 2) { fprintf(stderr, "usage: %s file\n", argv[0]); return 2; }
    f = fopen(argv[1], "r");
    if (!f) { perror(argv[1]); return 2; }
    while (fgets(line, sizeof line, f)) {
        char *tok, *save, kind[16];
        num_t a[20], x[4];
        dec_t want[4];
        int n, i, nv, have_sol = 0;
        calc_err_t er;
        ln++;
        if (line[0] == '#' || line[0] == '\n') continue;
        tok = strtok_r(line, " \n", &save);
        strcpy(kind, tok);
        n = atoi(strtok_r(NULL, " \n", &save));
        nv = n * (n + 1);
        for (i = 0; i < nv; i++) {
            dec_t d;
            tok = strtok_r(NULL, " \n", &save);
            if (!tok || dec_from_str(&d, tok) != DEC_OK) { printf("%s:%d: bad coefficient\n", argv[1], ln); fails++; goto next; }
            num_from_dec(&a[i], &d);
        }
        tok = strtok_r(NULL, " \n", &save);
        if (tok && strcmp(tok, "|") == 0) {
            have_sol = 1;
            for (i = 0; i < n; i++) {
                tok = strtok_r(NULL, " \n", &save);
                if (!tok || dec_from_str(&want[i], tok) != DEC_OK) { printf("%s:%d: bad solution\n", argv[1], ln); fails++; goto next; }
            }
        }
        cases++;
        er = eqn_simul(n, a, x);
        if (strcmp(kind, "unique") == 0) {
            if (er != CE_OK || !have_sol) { printf("%s:%d: expected a unique solution, got error %d\n", argv[1], ln, (int)er); fails++; continue; }
            for (i = 0; i < n; i++) {
                dec_t diff, ad, aw, lim, rel;
                dec_sub(&diff, &x[i].v, &want[i]); dec_abs(&ad, &diff);
                dec_abs(&aw, &want[i]);
                dec_from_str(&rel, "1E-9");
                dec_mul(&lim, &aw, &rel);
                {   /* absolute floor 1e-12 of the largest solution component for tiny entries */
                    dec_t floor_;
                    dec_from_str(&floor_, "1E-12");
                    if (dec_cmp(&lim, &floor_) < 0) lim = floor_;
                }
                if (dec_cmp(&ad, &lim) > 0) {
                    char g[40], w[40];
                    dec_to_str(&x[i].v, g, sizeof g); dec_to_str(&want[i], w, sizeof w);
                    printf("%s:%d: x%d got %s expected %s\n", argv[1], ln, i + 1, g, w);
                    fails++;
                    break;
                }
            }
        } else if (strcmp(kind, "inconsistent") == 0) {
            if (er != CE_INCONS) { printf("%s:%d: expected No Solution, got %d\n", argv[1], ln, (int)er); fails++; }
        } else {
            if (er != CE_INFIN) { printf("%s:%d: expected Infinite Solutions, got %d\n", argv[1], ln, (int)er); fails++; }
        }
    next:;
    }
    fclose(f);
    printf("%s: %d cases, %d failures\n", argv[1], cases, fails);
    return fails != 0;
}
